/* 大白话速览补充（第一部分：古代） */

Object.assign(EVENT_PLAIN, {
  "zhanlu": "传说中黄帝部落与蚩尤部落的生死大战，黄帝赢了中国就归他领导。这个故事说明：我们祖先是从部落混战里一步步融合成一个大民族的。",
  "shangmie": "夏朝最后一个王夏桀残暴，商部落首领商汤起兵推翻他，建立商朝——中国历史上第一次\"改朝换代\"。规矩从此立下：王位不是永恒的，干得太坏就会被推翻。",
  "pangeng": "商朝前期老是搬家、内乱不断，盘庚力排众议把首都迁到殷（今河南安阳）后才稳定下来，之后273年没再迁都。今天考古挖出的\"殷墟\"和甲骨文，就是那时候留下的。",
  "wuding": "商王武丁从底层提拔人才、让王后妇好带兵打仗，把商朝推向最强盛。他媳妇妇好是中国历史上第一位有文字记载的女将军。",
  "jinwen": "公子重耳被追杀，流浪列国19年，62岁才回国当上晋文公，马上称霸中原。跟对人的回报：一路陪他吃苦的臣子都成了开国功臣。",
  "zhanguo-bianfa": "战国初期各国搞\"军备竞赛式改革\"：谁改革谁变强，不改革就挨打。魏国最早变法最早称霸，为后来商鞅在秦国的大变法提供了样板。",
  "hufu": "赵武灵王让中原人改穿少数民族的短衣长裤、学骑马射箭——相当于一场\"服装革命+军事革命\"。脱掉长袍才能打仗，改革有时就得先改观念。",
  "hezong-lianheng": "战国版的\"合纵连横\"外交战：六国联合抗秦叫合纵，秦国拆散联盟各个击破叫连横。苏秦张仪凭嘴皮子搅动天下，最后秦国靠连横赢了。",
  "xiangru": "蔺相如靠智慧和胆量两次为国争光，官升到老将廉颇之上；廉颇不服要找茬，蔺相如处处躲让——为国不计私仇，廉颇背荆条上门道歉，两人成生死之交。\"负荆请罪\"的出处。",
  "quyuan": "楚国大夫屈原忠心报国却被两次流放，眼看祖国都城被秦国攻破，五月初五抱石投江。百姓划船抢救、投米团防鱼吃他——这就是端午节的由来。",
  "qiefu": "秦国围了赵国首都，魏国怕秦不敢救。信陵君偷了魏王的兵符、锤杀大将夺得八万兵权，硬是把秦军打跑了——为救邻国敢抗王命，战国四公子的巅峰操作。",
  "jingke": "弱国燕国对付不了强秦，只能派刺客。荆轲假装献地图，图穷匕见追杀秦王，失败被杀。\"风萧萧兮易水寒\"——明知必死仍去的悲壮，感动中国人两千年。",
  "dujiangyan": "李冰父子修的水利工程，不用大坝就让岷江自动分流排沙，成都平原从此旱涝保收成了\"天府之国\"。用了2200多年，今天还在灌溉千万亩良田——古代工程的天花板。",
  "qin-zhongyang": "秦始皇给后世定的\"操作系统\"：全国分成郡县由中央任命官员、书同文车同轨、皇帝说了算。此后两千年不管谁当政，基本都用这套制度。",
  "hanchu": "汉朝刚建立时穷得皇帝凑不齐四匹同色的马。政府放水养鱼：轻徭薄赋、尽量不管，六十年后粮仓爆满、钱串子烂掉——为汉武帝的大反击攒足了本钱。",
  "simaqian": "司马迁为败将李陵说了几句公道话，被汉武帝处以宫刑（奇耻大辱）。他忍辱活着，只为写完从黄帝到汉武帝的三千年史书——《史记》，\"史家之绝唱\"。",
  "zhaojun": "宫女王昭君自愿远嫁匈奴单于，换来汉匈60年无战争。个人的婚姻换千万人的和平，后世一直纪念她。",
  "zhaoxuan": "汉武帝连年打仗花光了家底，昭帝宣帝两朝接着攒钱、整顿吏治，西汉国势反而达到顶峰——会花钱也要会攒钱。",
  "banchao": "班超原本是个抄书员，扔了笔说\"大丈夫当立功异域\"，带36个人靠胆略收服西域五十多国，当了几十年\"西域总督\"。\"投笔从戎\"和\"不入虎穴焉得虎子\"都出自他。",
  "cailun-zhangheng": "东汉两大发明：蔡伦改进造纸术（知识从此便宜到人人可用），张衡发明地动仪（世界第一台测地震方位的仪器）。中国古代科技的高光时刻。",
  "dongzhuo": "军阀董卓带兵进首都，废皇帝、烧宫殿、随便杀人，把中央权威彻底踩碎。各地组成联军讨伐他，他死后中国进入群雄割据的三国前夜。",
  "sangu-mao": "刘备三顾茅庐请出27岁的诸葛亮。诸葛亮为他画出\"三分天下\"的战略蓝图，此后刘备集团的发展基本照着这张图走——一次面试改变了三国格局。",
  "guanyu-shijin": "关羽北伐打得太猛，背后盟友东吴偷袭了他的根据地荆州，关羽败走被杀。刘备为报仇又大败——三国鼎立的版图就此锁死。",
  "baidi": "刘备病危，把国家和儿子托付给诸葛亮，说了句惊人的话：\"我儿子不行你就自己取代他。\"诸葛亮哭着表忠心，之后辅佐刘禅十一年直至死在岗位上。",
  "gaopingling": "老谋士司马懿装病十年骗过对手，趁其出城扫墓发动政变，一天之内夺取曹魏政权。司马家从此掌权，最终孙子篡位建晋——\"司马昭之心路人皆知\"。",
  "zuti": "祖逖半夜听到鸡叫就起来练剑。南渡后朝廷不给兵，他自己招募北伐，收复黄河以南，却遭猜忌忧郁而死。\"闻鸡起舞\"的男主角，壮志未酬的典型。",
  "lanting": "书法家王羲之和41位朋友春游喝酒写诗，微醉中写下一篇序——324个字的《兰亭集序》，被誉为\"天下第一行书\"。酒醒后他自己都写不出那么好了。",
  "nanbeikeji": "南北朝大乱世里，祖冲之把圆周率算到小数点后7位，领先世界近千年。乱世不只有杀戮，也有科学的火种。",
  "taoyuanming": "县令陶渊明不愿为五斗米向上司点头哈腰，辞职回家种田采菊。他写的桃花源成为中国人心中\"理想世界\"的代名词。",
  "suidai-qiyi": "隋炀帝修运河、打高丽把民力耗尽，民间起义遍地开花。贵族李渊趁机起兵，捡起隋朝的制度遗产建立唐朝——隋朝是\"建设者+牺牲品\"。",
  "xuanzang": "唐僧的原型：玄奘偷渡出境，徒步5万里去印度取经，留学17年成为顶级学者后载誉回国译经。真实经历比《西游记》更传奇。",
  "wencheng": "唐朝把宗室女文成公主嫁给吐蕃赞普松赞干布，带去佛像、书籍、工匠和技术。汉藏从此成一家人，拉萨至今供奉着她。",
  "shengtang-shige": "盛唐诗歌的黄金时代：李白浪漫、杜甫深沉、王维空灵……五万多首唐诗是中国人的\"精神母语\"，小孩背的第一首诗多半来自这里。",
  "jianzhen": "高僧鉴真东渡日本传戒，五次失败、双目失明仍不放弃，第六次成功。他把佛法、建筑、医药带到日本，日本人尊他为文化恩人。",
  "guoziyi-dahui": "唐将郭子仪不带武器、单人骑马走进叛军大营，靠个人威望让30万敌军下拜倒戈。\"不战而屈人之兵\"的实战范本。",
  "wudai-kaiju": "唐朝灭亡后53年里换了5个朝代、十几拨皇帝，武人当政有兵就是王。直到柴荣改革和赵匡胤建立宋朝才终结这场混乱。",
  "xining": "王安石给宋朝开的\"富国强兵\"药方：青苗法（政府低息贷款）等新法让国库充盈，但执行走样、党争撕裂朝堂。他死后新法尽废，宋朝错过自救机会。",
  "sida-faming": "造纸、印刷、火药、指南针四大发明在宋代全部成熟，随后传入欧洲，改变了全世界——马克思说它们\"预告了资产阶级社会的到来\"。",
  "songci": "宋词是宋代的\"流行歌词\"：苏轼豪放、李清照婉约、辛弃疾铿锵……两万多首宋词与唐诗并峙，是中国文学的另一座高峰。",
  "yuan-tongyi": "忽必烈建元朝第一次由少数民族统一全中国，行省制度（今天\"省\"的由来）、西藏直辖、大运河截弯取直都出自元朝。马可·波罗笔下的东方奇迹。",
  "hongjin": "\"石人一只眼，挑动黄河天下反\"——治河民工挖出预埋的石人，红巾军大起义爆发。放牛娃出身的朱元璋从起义军里崛起，最终建立明朝。",
  "poyanghu": "朱元璋与陈友谅决战鄱阳湖，36天水战以少胜多，陈友谅中箭死。这是中世纪世界最大水战，扫清了朱元璋统一路上最强对手。",
  "ming-kaiguo": "朱元璋从乞丐、和尚一路当上皇帝，创造中国历史最励志逆袭。徐达北伐收复燕云十六州——汉族政权四百年来第一次收复北方全线。",
  "hulan-zhiyu": "朱元璋为保子孙皇位，制造两大案杀功臣近5万，还借机废掉了丞相职位。从此皇帝直接管六部，皇权空前集中——也为明朝的宦官专权埋下伏笔。",
  "yongle": "朱棣迁都北京\"天子守国门\"，编成3.7亿字的《永乐大典》（世界最大百科全书），派郑和七下西洋。篡位者的文治武功反而造就明朝巅峰。",
  "beijing-baowei": "皇帝被俘、首都危急，兵部侍郎于谦拥立新帝、列阵九城之外背城一战，把瓦剌打退。\"社稷为重君为轻\"——救了国家，八年后却被复辟的旧皇帝冤杀。",
  "ming-sanjuzhu": "明代三本科技巨著：李时珍《本草纲目》（药）、宋应星《天工开物》（工农技术）、徐光启《农政全书》（农业）——传统科技的总结巅峰。",
  "ningyuan": "袁崇焕凭坚城大炮打死所向无敌的努尔哈赤——后金起兵以来第一场大败。三年后皇太极用反间计借崇祯之手凌迟了袁崇焕。",
  "pinggeer": "噶尔丹想当草原霸主，康熙三次御驾亲征把他打到众叛亲离自尽。外蒙古正式纳入版图，清朝疆域再扩一大块。",
  "tuerhute": "土尔扈特部不堪沙俄压迫，17万人万里东迁回新疆，到达时只剩7万。乾隆妥善安置——人类迁徙史上的悲壮史诗。",
  "sikuzhishu": "乾隆编《四库全书》收书近8万卷，是文化总汇；但同时借征书禁毁三千多种书、大兴文字狱——\"修书\"与\"毁书\"一体两面。",
  "caopi-chanhan": "曹操的儿子曹丕逼汉献帝\"禅让\"，412年的汉朝落幕。此后\"禅让\"成了篡位的固定剧本，被用了好几百年。",
  "qingli-xinzheng": "范仲淹庆历新政：整顿官僚、考核政绩、限制恩荫，触怒利益集团仅一年就失败。但它为王安石变法趟了路，\"先天下之忧而忧\"成了士大夫精神标杆。",
  "yuan-wenhua": "黄道婆把黎族纺织技术带回上海改良推广，松江布\"衣被天下\"；关汉卿们写杂剧，元曲与唐诗宋词并列——普通人的衣食与娱乐在元代大升级。",
  "junjichu": "雍正设立军机处，大臣\"跪受笔录\"，皇帝集权到顶点；同时\"摊丁入亩\"废掉人头税——穷人负担大减，人口随后破三亿。",
  "shengtang-shiren": "李白杜甫在洛阳相遇，同游梁宋，\"醉眠秋共被\"——中国文学史上太阳与月亮的相会。高适贺知章王维等群星同场，构成盛唐最强朋友圈。",
  "guwen-yundong": "韩愈柳宗元发起\"古文运动\"：反对华丽空洞的骈文，提倡言之有物的散文。今天的中文写作范式基本由此定型。",
  "ming-qing-xiaoshuo": "明清小说黄金时代：四大名著加《聊斋》《儒林外史》都在这三百年问世。小说取代诗歌成为主流——市民社会兴起，老百姓爱看故事。",
  "minguo-wenxue": "白话文定型的一代：老舍写北平、巴金控诉封建家庭、沈从文唱湘西牧歌、曹禺立话剧丰碑……今天的中文文体基本是这批人奠定的。",
  "shoufu-taiwan": "郑成功率两万五千人渡海，围城九个月逼荷兰人签降约——中国第一次从西方殖民者手里夺回大片领土。沦陷38年的台湾回来了。",
  "nanming-kangqing": "明朝灭亡后李定国等抵抗了18年，1652年一年内逼死一个清王、阵斩一个清王（\"两蹶名王，天下震动\"），清廷一度想放弃西南。内讧最终葬送了大好局面。"
});
